def _batchim_index(word: str) -> int:
    """Return the final-consonant index for the last Hangul syllable."""
    last = word[-1]
    code = ord(last) - 0xAC00
    return code % 28 if 0 <= code <= 11171 else 0


def _particle(word: str, with_batchim: str, without_batchim: str) -> str:
    """Attach a basic Korean particle according to the final Hangul syllable."""
    return f"{word}{with_batchim if _batchim_index(word) else without_batchim}"


def _directional(word: str) -> str:
    """Attach 으로/로, including the ㄹ-final exception."""
    return f"{word}{'으로' if _batchim_index(word) not in (0, 8) else '로'}"


def _entry(position: int, motif_index: int, perspective_index: int) -> dict:
    slug, focus, scene, signal, question, action, caution, insight = MOTIFS[motif_index]
    p_name, approach, tension, value, method, counterpoint = PERSPECTIVES[perspective_index]
    work = SCHEDULE[(position - 1) % len(SCHEDULE)]
    flow = FLOWS[(position - 1) % len(FLOWS)]
    lens = f"{focus}의 {p_name}"
    focus_obj = _particle(focus, "을", "를")
    focus_topic = _particle(focus, "은", "는")
    lens_obj = _particle(lens, "을", "를")
    p_name_obj = _particle(p_name, "을", "를")
    p_name_topic = _particle(p_name, "은", "는")
    p_name_subject = _particle(p_name, "이", "가")
    p_name_directional = _directional(p_name)
    approach_obj = _particle(approach, "을", "를")
    approach_topic = _particle(approach, "은", "는")
    tension_obj = _particle(tension, "을", "를")
    scene_obj = _particle(scene, "을", "를")
    signal_topic = _particle(signal, "은", "는")
    signal_and = _particle(signal, "과", "와")
    caution_topic = _particle(caution, "은", "는")
    title = f"{focus}에서 배우는 {p_name}: {question}"
